using Ocelot.DependencyInjection;
using Ocelot.Middleware;

var builder = WebApplication.CreateBuilder(args);

builder.Configuration
    .AddJsonFile("ocelot.json", optional: false, reloadOnChange: true)
    .AddEnvironmentVariables();

builder.Services.AddControllers();
builder.Services.AddHealthChecks()
    .AddUrlGroup(new Uri("http://authservice:8080/health"), "auth-service")
    .AddUrlGroup(new Uri("http://userservice:8080/health"), "user-service")
    .AddUrlGroup(new Uri("http://profileservice:8080/health"), "profile-service")
    .AddUrlGroup(new Uri("http://discoveryservice:8080/health"), "discovery-service")
    .AddUrlGroup(new Uri("http://bookingservice:8080/health"), "booking-service")
    .AddUrlGroup(new Uri("http://paymentservice:8080/health"), "payment-service")
    .AddUrlGroup(new Uri("http://chatservice:8080/health"), "chat-service")
    .AddUrlGroup(new Uri("http://notificationservice:8080/health"), "notification-service")
    .AddUrlGroup(new Uri("http://reviewservice:8080/health"), "review-service")
    .AddUrlGroup(new Uri("http://supportservice:8080/health"), "support-service")
    .AddUrlGroup(new Uri("http://analyticsservice:8080/health"), "analytics-service");
builder.Services.AddOcelot();

var app = builder.Build();

app.UseHttpsRedirection();
app.UseRouting();
app.UseAuthorization();

// Native health check endpoints (handles /ready, /health, /health/ready)
app.MapHealthChecks("/ready");
app.MapHealthChecks("/health");
app.MapHealthChecks("/health/ready");

// Root route
app.MapGet("/", () => "APIGateway is running");
app.MapControllers();

// Hand over unhandled routes to Ocelot Gateway pipeline
await app.UseOcelot();
app.Run();

